package com.spendwise.config;import com.spendwise.auth.AuthService;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.web.authentication.WebAuthenticationDetailsSource;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;import java.util.List;
@Component public class JwtAuthFilter extends OncePerRequestFilter{private final AuthService auth;public JwtAuthFilter(AuthService a){auth=a;}@Override protected void doFilterInternal(HttpServletRequest q,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String h=q.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")&&SecurityContextHolder.getContext().getAuthentication()==null){try{var a=new UsernamePasswordAuthenticationToken(auth.verify(h.substring(7)),null,List.of());a.setDetails(new WebAuthenticationDetailsSource().buildDetails(q));SecurityContextHolder.getContext().setAuthentication(a);}catch(RuntimeException e){SecurityContextHolder.clearContext();}}c.doFilter(q,s);}}